extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var menu := await instantiate_scene("res://main_menu.tscn")
	if not check("menu_loaded", menu != null, "La scena res://main_menu.tscn deve potersi istanziare senza errori"):
		return

	var start_btn := find_by_name(menu, "StartButton") as Button
	var quit_btn := find_by_name(menu, "QuitButton") as Button
	var high_label := find_by_name(menu, "HighScoreLabel") as Label

	check("start_button", start_btn != null, "Nel menu principale deve esserci un Button chiamato StartButton")
	check("quit_button", quit_btn != null, "Nel menu principale deve esserci un Button chiamato QuitButton")
	check("high_score_label", high_label != null, "Nel menu principale deve esserci un Label chiamato HighScoreLabel")

	var save_manager_node = get_tree().root.get_node_or_null("SaveManager")
	if check("save_manager", save_manager_node != null, "L'Autoload SaveManager deve essere registrato nel progetto"):
		save_manager_node.call("save_high_score", 50)
		var loaded_score: int = save_manager_node.call("get_high_score")
		check("save_load", loaded_score >= 50, "SaveManager deve salvare e ricaricare il record in user://high_score.json (letto %d)" % loaded_score)

	var arena := await instantiate_scene("res://arena.tscn")
	if not check("arena_loaded", arena != null, "La scena res://arena.tscn deve potersi istanziare"):
		return

	var player := find_by_name(arena, "Player") as CharacterBody2D
	if check("player_exists", player != null, "Nell'Arena deve esserci il nodo Player"):
		var health := player.get_node_or_null("Health") as Health
		if check("health_exists", health != null, "Player deve avere il componente Health"):
			health.take_damage(9999)
			await wait_frames(5)
			var game_over := find_by_name(arena, "GameOverScreen") as CanvasLayer
			if game_over == null:
				game_over = find_by_class(arena, "GameOverScreen") as CanvasLayer
			check("game_over_visible", game_over != null and game_over.visible and get_tree().paused, "Alla morte del giocatore deve comparire GameOverScreen e il gioco deve andare in pausa")
			get_tree().paused = false

	var arena_perf := await instantiate_scene("res://arena.tscn")
	var enemy_scene := load("res://enemy.tscn") as PackedScene
	if enemy_scene and arena_perf:
		var start_time := Time.get_ticks_usec()
		for i in range(100):
			var enemy := enemy_scene.instantiate() as Node2D
			enemy.position = Vector2(randf_range(50, 1100), randf_range(50, 600))
			arena_perf.add_child(enemy)
		await wait_physics_frames(10)
		var elapsed_ms := (Time.get_ticks_usec() - start_time) / 1000.0
		check("perf_100_enemies", elapsed_ms < 500.0, "La gestione di 100 nemici contemporanei deve avvenire senza rallentamenti (tempo calcolo: %.2f ms)" % elapsed_ms)

