@export var speed: float = 500.0
@export var damage: int = 10
var direction: Vector2 = Vector2.RIGHT
var lifetime: float = 2.0


func _ready() -> void:
	body_entered.connect(_on_body_entered)


func _physics_process(delta: float) -> void:
	position += direction * speed * delta
	lifetime -= delta
	if lifetime <= 0.0:
		queue_free()


func _on_body_entered(body: Node2D) -> void:
	if body.is_in_group("enemies") or body is Enemy:
		var health := body.get_node_or_null("Health") as Health
		if health:
			health.take_damage(damage)
		queue_free()
	elif body.name == "Walls":
		queue_free()

extends Node

const SAVE_PATH := "user://high_score.json"


func get_high_score() -> int:
	if not FileAccess.file_exists(SAVE_PATH):
		return 0
	var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
	if file == null:
		return 0
	var json_text := file.get_as_text()
	file.close()
	var data = JSON.parse_string(json_text)
	if data is Dictionary and data.has("high_score"):
		return int(data["high_score"])
	return 0


func save_high_score(score: int) -> void:
	var current_high := get_high_score()
	if score > current_high:
		var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
		if file:
			var data := {"high_score": score}
			file.store_string(JSON.stringify(data))
			file.close()

