extends Node2D

@export var enemy_scene: PackedScene = preload("res://enemy.tscn")
@export var upgrade_screen_scene: PackedScene = preload("res://upgrade_screen.tscn")
@export var waves: Array[WaveData] = []:
	set(value):
		waves = value
		current_wave_index = 0
		spawned_in_wave = 0
		spawn_timer = 0.0

@onready var pause_menu: PauseMenu = $PauseMenu
@onready var game_over_screen: GameOverScreen = $GameOverScreen
@onready var player: CharacterBody2D = $Player

var current_wave_index: int = 0
var spawned_in_wave: int = 0
var spawn_timer: float = 0.0
var waiting_for_next_wave: bool = false
var upgrade_screen_instance: UpgradeScreen = null


func _ready() -> void:
	if waves.is_empty():
		_setup_default_waves()
	spawn_timer = 0.0

	if upgrade_screen_scene:
		upgrade_screen_instance = upgrade_screen_scene.instantiate() as UpgradeScreen
		add_child(upgrade_screen_instance)
		upgrade_screen_instance.upgrade_selected.connect(_on_upgrade_selected)

	if player:
		var health := player.get_node_or_null("Health") as Health
		if health:
			health.died.connect(_on_player_died)


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("pause"):
		if pause_menu and not get_tree().paused:
			pause_menu.toggle_pause()
		elif pause_menu and pause_menu.visible:
			pause_menu.toggle_pause()


func _setup_default_waves() -> void:
	var fast_res = load("res://enemies/fast_enemy.tres") as EnemyData
	var normal_res = load("res://enemies/normal_enemy.tres") as EnemyData
	var tank_res = load("res://enemies/tank_enemy.tres") as EnemyData

	var w1 := WaveData.new()
	w1.spawn_count = 5
	w1.spawn_interval = 1.0
	if normal_res:
		w1.enemy_types.append(normal_res)

	var w2 := WaveData.new()
	w2.spawn_count = 8
	w2.spawn_interval = 0.8
	if fast_res:
		w2.enemy_types.append(fast_res)
	if normal_res:
		w2.enemy_types.append(normal_res)

	var w3 := WaveData.new()
	w3.spawn_count = 12
	w3.spawn_interval = 0.6
	if fast_res:
		w3.enemy_types.append(fast_res)
	if normal_res:
		w3.enemy_types.append(normal_res)
	if tank_res:
		w3.enemy_types.append(tank_res)

	waves = [w1, w2, w3]


func _process(delta: float) -> void:
	if current_wave_index >= waves.size():
		return

	var wave := waves[current_wave_index]

	if waiting_for_next_wave:
		return

	if spawned_in_wave < wave.spawn_count:
		spawn_timer -= delta
		if spawn_timer <= 0.0:
			spawn_enemy(wave)
			spawned_in_wave += 1
			spawn_timer = wave.spawn_interval
	else:
		var enemies := get_tree().get_nodes_in_group("enemies")
		if enemies.is_empty():
			waiting_for_next_wave = true
			if upgrade_screen_instance:
				upgrade_screen_instance.open()
			else:
				_start_next_wave()


func _on_upgrade_selected(upgrade_id: String) -> void:
	if player and player.has_method("apply_upgrade"):
		player.apply_upgrade(upgrade_id)
	_start_next_wave()


func _start_next_wave() -> void:
	waiting_for_next_wave = false
	current_wave_index += 1
	spawned_in_wave = 0
	spawn_timer = 0.0


func spawn_enemy(wave: WaveData) -> void:
	if enemy_scene == null or wave.enemy_types.is_empty():
		return
	var enemy := enemy_scene.instantiate() as Enemy
	var type_data: EnemyData = wave.enemy_types.pick_random()
	enemy.data = type_data

	var side := randi() % 4
	var pos := Vector2.ZERO
	match side:
		0: pos = Vector2(randf_range(-40, 1192), -40)
		1: pos = Vector2(randf_range(-40, 1192), 688)
		2: pos = Vector2(-40, randf_range(-40, 688))
		3: pos = Vector2(1192, randf_range(-40, 688))
	enemy.global_position = pos
	add_child(enemy)


func _on_player_died() -> void:
	var exp_amount: int = 0
	if player and "experience" in player:
		exp_amount = int(player.get("experience"))
	if game_over_screen:
		game_over_screen.show_game_over(exp_amount)

class_name Enemy
extends CharacterBody2D

@export var data: EnemyData:
	set(value):
		data = value
		if is_node_ready() and health and data:
			health.max_health = data.max_health
			health.current_health = data.max_health

@export var gem_scene: PackedScene = preload("res://experience_gem.tscn")

@onready var health: Health = $Health

var player: Node2D = null


func _ready() -> void:
	add_to_group("enemies")
	if data:
		health.max_health = data.max_health
		health.current_health = data.max_health

	health.died.connect(_on_died)
	var players := get_tree().get_nodes_in_group("player")
	if not players.is_empty():
		player = players[0] as Node2D
	else:
		player = get_parent().get_node_or_null("Player") as Node2D


func _physics_process(_delta: float) -> void:
	if player == null:
		player = get_parent().get_node_or_null("Player") as Node2D

	if player:
		var direction := (player.global_position - global_position).normalized()
		var spd := data.speed if data else 100.0
		velocity = direction * spd
		move_and_slide()

		if global_position.distance_to(player.global_position) < 24.0:
			var player_health := player.get_node_or_null("Health") as Health
			if player_health:
				var dmg := data.damage if data else 10
				player_health.take_damage(dmg)
			queue_free()


func _on_died() -> void:
	if gem_scene:
		var gem := gem_scene.instantiate() as Node2D
		gem.global_position = global_position
		get_parent().add_child(gem)
	queue_free()

class_name ExperienceGem
extends Area2D

@export var amount: int = 10

var audio_player: AudioStreamPlayer = null


func _ready() -> void:
	add_to_group("experience")
	body_entered.connect(_on_body_entered)

	audio_player = AudioStreamPlayer.new()
	audio_player.stream = load("res://assets/audio/coin.wav") as AudioStream
	add_child(audio_player)


func _on_body_entered(body: Node2D) -> void:
	if body.name == "Player" or body.has_method("add_experience"):
		if body.has_method("add_experience"):
			body.add_experience(amount)
		elif "experience" in body:
			body.set("experience", int(body.get("experience")) + amount)

		if audio_player and audio_player.stream:
			audio_player.play()

		visible = false
		set_deferred("monitoring", false)
		await get_tree().create_timer(0.3).timeout
		queue_free()
